-- Exclusivamente banco temporário descartável: usa COMMIT para duas sessões.
-- Não executar em ambiente compartilhado ou com conexão externa ao Storage.
do $$begin if current_database()<>'sso_foto_0975_tmp_20261030' then raise exception 'banco_descartavel_exigido'; end if;end$$;
create extension if not exists pgtap with schema extensions;
create extension if not exists dblink with schema extensions;
set search_path=public,extensions;
select plan(6);
begin;
set local app.auvo_sync_write='true';
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values ('17981000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','corrida-foto@example.test',crypt('x',gen_salt('bf')),'{}','{}',now(),now());
insert into config.usuarios(user_id,papel,nome,ativo) values ('17981000-0000-0000-0000-000000000001','colaborador','Corrida foto',true);
insert into config.usuario_modulos(user_id,modulo,nivel) values ('17981000-0000-0000-0000-000000000001','pcm','escrita');
insert into pcm.clientes(id,nome,ativo,created_by) values ('17981000-0000-0000-0000-00000000000a','Cliente corrida foto',true,'17981000-0000-0000-0000-000000000001');
insert into config.sso_concessoes(usuario_id,acao,cliente_id) values ('17981000-0000-0000-0000-000000000001','cadastro.aprovar','17981000-0000-0000-0000-00000000000a');
insert into pcm.sso_levantamentos(id,cliente_id,origem,chave_origem,conteudo,criado_por) values ('17981000-0000-0000-0000-000000000021','17981000-0000-0000-0000-00000000000a','manual','corrida-foto','[]','17981000-0000-0000-0000-000000000001');
insert into pcm.sso_levantamento_linhas(lote_id,chave,tipo,atributos) values ('17981000-0000-0000-0000-000000000021','a','sistema','{}');
update pcm.sso_ingestao_foto_gate set habilitado=true where id;
update pcm.sso_fotos_levantamento_gate set habilitado=true where id;
select pcm.sso_ingestao_foto_servico('reservar','17981000-0000-0000-0000-000000000001','17981000-0000-0000-0000-000000000041','17981000-0000-0000-0000-000000000021','a',repeat('a',64),null);
insert into storage.objects(id,bucket_id,name) select '17981000-0000-0000-0000-000000000051','sso-levantamento-fotos',nome from pcm.sso_ingestao_foto_reservas where request_id='17981000-0000-0000-0000-000000000041';
commit;
select extensions.dblink_connect('s178a','dbname='||current_database());
select extensions.dblink_connect('s178b','dbname='||current_database());
select extensions.dblink_exec('s178a','begin');
select extensions.dblink_exec('s178b','begin');
select extensions.dblink_exec('s178a','set local app.auvo_sync_write = ''true''');
select extensions.dblink_exec('s178b','set local app.auvo_sync_write = ''true''');
select extensions.dblink_exec('s178b','set local application_name = ''s178_foto_b''');
select extensions.dblink_exec('s178a','set local role service_role');
select extensions.dblink_exec('s178b','set local role service_role');
create temporary table s178_resultado_a as select resultado from extensions.dblink('s178a',$sql$select pcm.sso_ingestao_foto_servico('confirmar','17981000-0000-0000-0000-000000000001','17981000-0000-0000-0000-000000000041','17981000-0000-0000-0000-000000000021','a',repeat('a',64),'17981000-0000-0000-0000-000000000051')$sql$) as t(resultado jsonb);
select extensions.dblink_send_query('s178b',$sql$select pcm.sso_ingestao_foto_servico('confirmar','17981000-0000-0000-0000-000000000001','17981000-0000-0000-0000-000000000041','17981000-0000-0000-0000-000000000021','a',repeat('a',64),'17981000-0000-0000-0000-000000000051')$sql$);
select is(extensions.dblink_is_busy('s178b'),1,'segunda confirmação permanece em curso enquanto primeira transação está aberta');
do $$begin for i in 1..100 loop perform pg_stat_clear_snapshot(); exit when exists(select 1 from pg_stat_activity where datname=current_database() and application_name='s178_foto_b' and wait_event_type='Lock'); perform pg_sleep(0.01); end loop;end$$;
select ok(exists(select 1 from pg_stat_activity where datname=current_database() and application_name='s178_foto_b' and wait_event_type='Lock'),'segunda sessão aguarda bloqueio real antes do commit');
select extensions.dblink_exec('s178a','commit');
create temporary table s178_resultado_b as select resultado from extensions.dblink_get_result('s178b') as t(resultado jsonb);
select count(*) from extensions.dblink_get_result('s178b') as t(resultado jsonb);
select extensions.dblink_exec('s178b','commit');
select is((select resultado->>'fotoId' from s178_resultado_a),(select resultado->>'fotoId' from s178_resultado_b),'confirmações concorrentes convergem na mesma foto');
select is((select count(*)::integer from pcm.sso_fotos_levantamento where request_id='17981000-0000-0000-0000-000000000041'),1,'uma única foto confirmada');
select is(pcm.sso_recuperar_objeto_ingestao_servico('17981000-0000-0000-0000-000000000001','17981000-0000-0000-0000-000000000041','17981000-0000-0000-0000-000000000021','a',repeat('a',64))->>'objetoId','17981000-0000-0000-0000-000000000051','replay localiza o mesmo objeto');
update config.sso_concessoes set ativa=false where usuario_id='17981000-0000-0000-0000-000000000001';
select throws_ok($$select pcm.sso_recuperar_objeto_ingestao_servico('17981000-0000-0000-0000-000000000001','17981000-0000-0000-0000-000000000041','17981000-0000-0000-0000-000000000021','a',repeat('a',64))$$,'42501',null,'replay após revogação é negado');
select extensions.dblink_disconnect('s178a');
select extensions.dblink_disconnect('s178b');
select * from finish();
